import React, { useState } from 'react';

const MaintenanceHistory = ({ maintenanceHistory }) => {
  const [statusFilter, setStatusFilter] = useState('all');
  const [typeFilter, setTypeFilter] = useState('all');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const filteredHistory = maintenanceHistory.filter(record => {
    // Status filter
    if (statusFilter !== 'all' && record.status !== statusFilter) {
      return false;
    }

    // Type filter (if exists in record)
    if (typeFilter !== 'all' && record.type && record.type !== typeFilter) {
      return false;
    }

    // Date filter
    if (startDate && record.timestamp) {
      const recordDate = record.timestamp instanceof Date 
        ? record.timestamp 
        : new Date(record.timestamp.seconds * 1000);

      const filterStartDate = new Date(startDate);
      if (recordDate < filterStartDate) {
        return false;
      }
    }

    if (endDate && record.timestamp) {
      const recordDate = record.timestamp instanceof Date 
        ? record.timestamp 
        : new Date(record.timestamp.seconds * 1000);

      const filterEndDate = new Date(endDate);
      filterEndDate.setHours(23, 59, 59);
      if (recordDate > filterEndDate) {
        return false;
      }
    }

    return true;
  });

  // Helper function to format timestamp
  const formatDate = (timestamp) => {
    if (!timestamp) return 'N/A';

    const date = timestamp instanceof Date 
      ? timestamp 
      : new Date(timestamp.seconds * 1000);

    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="maintenance-history">
      <h2>Maintenance History</h2>
      <p>View and filter maintenance records from the database.</p>

      <div className="history-filters">
        <select 
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
        >
          <option value="all">All Statuses</option>
          <option value="completed">Completed</option>
          <option value="pending">Pending</option>
          <option value="in-progress">In Progress</option>
        </select>

        <select
          value={typeFilter}
          onChange={(e) => setTypeFilter(e.target.value)}
        >
          <option value="all">All Types</option>
          <option value="Routine Check">Routine Check</option>
          <option value="Maintenance">Maintenance</option>
          <option value="Repair">Repair</option>
          <option value="Emergency">Emergency</option>
        </select>

        <div className="date-range">
          <input 
            type="date" 
            placeholder="Start Date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
          />
          <input 
            type="date" 
            placeholder="End Date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
          />
        </div>
      </div>

      {filteredHistory.length === 0 ? (
        <div className="no-records">
          <p>No maintenance records found.</p>
        </div>
      ) : (
        <table className="history-table">
          <thead>
            <tr>
              <th>Date</th>
              <th>Panel ID</th>
              <th>Technician</th>
              <th>Efficiency</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredHistory.map((record) => (
              <tr key={record.id}>
                <td>{formatDate(record.timestamp)}</td>
                <td>{record.panelId}</td>
                <td>{record.technicianName}</td>
                <td>{record.efficiency}%</td>
                <td>
                  <span className={`status-badge ${record.status}`}>
                    {record.status}
                  </span>
                </td>
                <td>
                  <button 
                    className="view-btn"
                    onClick={() => {
                      // View record details
                      console.log('View record:', record);
                    }}
                  >
                    View
                  </button>
                  <button 
                    className="edit-btn"
                    onClick={() => {
                      // Edit record
                      console.log('Edit record:', record);
                    }}
                  >
                    Edit
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default MaintenanceHistory;
